"use client";

import * as React from "react";
import {
  CartesianGrid,
  Line,
  LineChart as RechartsLineChart,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { cn } from "@/lib/utils";
import {
  AnimatedDashedStroke,
  ChartActiveDot,
  type ChartDatum,
  ChartFrame,
  ChartGlowFilter,
  chartGrid,
  ChartLegend,
  ChartLoadingBars,
  ChartPlotSurface,
  ChartRestingDot,
  type ChartSeries,
  ChartTooltipContent,
  chartXAxis,
  chartYAxis,
  type ChartDotRenderProps,
  compactFormatValue,
  RevealMask,
  resolveSeries,
  type StrokeVariant,
  strokeDasharray,
  useChartId,
  useChartMotion,
  useIntroStartedAt,
} from "@/components/moneytrees/charts/chart-kit";

export type LineCurve = "monotone" | "bump" | "step" | "linear";

export interface SpectrumLineChartProps {
  className?: string;
  data: ChartDatum[];
  xKey: string;
  series: ChartSeries[];
  curveType?: LineCurve;
  strokeVariant?: StrokeVariant;
  glowing?: boolean;
  gradientStroke?: boolean;
  isLoading?: boolean;
  showLegend?: boolean;
  showDots?: boolean;
  showGrid?: boolean;
  height?: number;
  formatX?: (value: string | number) => string;
  formatValue?: (value: number) => string;
}

export function LineChart({
  className,
  data,
  xKey,
  series,
  curveType = "monotone",
  strokeVariant = "solid",
  glowing = false,
  gradientStroke = false,
  isLoading = false,
  showLegend = true,
  showDots = true,
  showGrid = true,
  height,
  formatX,
  formatValue,
}: SpectrumLineChartProps) {
  const id = useChartId("line");
  const { reduce } = useChartMotion();
  const introStartedAt = useIntroStartedAt();
  const lines = resolveSeries(series);
  const glowId = `${id}-glow`;
  const maskId = `${id}-reveal`;
  const maskStyle = reduce ? undefined : { mask: `url(#${maskId})` };
  const dots = showDots && data.length <= 40;

  return (
    <ChartFrame className={cn("flex flex-col", className)} height={height}>
      {showLegend && lines.length > 1 ? <ChartLegend items={lines} /> : null}
      {isLoading ? (
        <ChartLoadingBars />
      ) : (
        <ChartPlotSurface>
          <ResponsiveContainer width="100%" height="100%">
            <RechartsLineChart data={data} margin={{ top: 8, right: 8, left: 0, bottom: 0 }}>
              <defs>
                {gradientStroke
                  ? lines.map((s, i) => (
                      <linearGradient
                        key={s.key}
                        id={`${id}-${s.key}-stroke`}
                        x1="0"
                        y1="0"
                        x2="1"
                        y2="0"
                      >
                        <stop offset="0%" stopColor={s.color} />
                        <stop offset="100%" stopColor={lines[(i + 1) % lines.length]!.color} />
                      </linearGradient>
                    ))
                  : null}
                {glowing ? <ChartGlowFilter id={glowId} /> : null}
                <RevealMask id={maskId} introStartedAt={introStartedAt} reduce={reduce} />
              </defs>
              {showGrid ? <CartesianGrid {...chartGrid} /> : null}
              <XAxis {...chartXAxis} dataKey={xKey} tickFormatter={formatX} />
              <YAxis {...chartYAxis} tickFormatter={formatValue ?? compactFormatValue} />
              <Tooltip
                cursor={{ stroke: "currentColor", strokeOpacity: 0.22, strokeDasharray: "4 4" }}
                content={<ChartTooltipContent formatValue={formatValue} formatLabel={formatX} />}
              />
              {lines.map((s, i) => (
                <Line
                  key={s.key}
                  type={curveType}
                  dataKey={s.key}
                  name={s.label}
                  stroke={
                    gradientStroke && lines.length > 1 ? `url(#${id}-${s.key}-stroke)` : s.color
                  }
                  strokeWidth={2.25}
                  strokeDasharray={strokeDasharray(strokeVariant)}
                  dot={
                    dots
                      ? (props: ChartDotRenderProps) => (
                          <ChartRestingDot
                            key={`dot-${props.index}`}
                            cx={props.cx}
                            cy={props.cy}
                            color={s.color}
                            maskId={reduce ? undefined : maskId}
                          />
                        )
                      : false
                  }
                  activeDot={(props: ChartDotRenderProps) => (
                    <ChartActiveDot
                      key={`active-${props.index}`}
                      cx={props.cx}
                      cy={props.cy}
                      color={s.color}
                    />
                  )}
                  isAnimationActive={false}
                  filter={glowing && i === 0 ? `url(#${glowId})` : undefined}
                  style={maskStyle}
                >
                  {strokeVariant === "animated-dashed" ? <AnimatedDashedStroke /> : null}
                </Line>
              ))}
            </RechartsLineChart>
          </ResponsiveContainer>
        </ChartPlotSurface>
      )}
    </ChartFrame>
  );
}
